def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], instance: np.ndarray, distance_matrix_1: np.ndarray, distance_matrix_2: np.ndarray, distance_matrix_3: np.ndarray) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a numpy array of node IDs.
             Each objective is a tuple of three float values.
    instance: Numpy array of shape (N, 4). Each row corresponds to a node and contains its coordinates in two 2D spaces: (x1, y1, x2, y2).
    distance_matrix_1: Distance matrix in the first objective space.
    distance_matrix_2: Distance matrix in the second objective space.
    distance_matrix_3: Distance matrix in the third objective space.

    Returns:
    A new neighbor solution (numpy array).
    """
    if len(archive) == 1:
        base_solution = archive[0][0].copy()
    else:
        objectives = np.array([obj for _, obj in archive])
        objective_ranges = np.max(objectives, axis=1) - np.min(objectives, axis=1)
        selected_idx = np.argmin(objective_ranges)
        base_solution = archive[selected_idx][0].copy()

    new_solution = base_solution.copy()
    n = len(new_solution)

    current_costs = [
        sum(distance_matrix_1[new_solution[i-1], new_solution[i]] for i in range(n)),
        sum(distance_matrix_2[new_solution[i-1], new_solution[i]] for i in range(n)),
        sum(distance_matrix_3[new_solution[i-1], new_solution[i]] for i in range(n))
    ]

    worst_obj = np.argmax(current_costs)

    segment_size = max(2, n // 4)
    segments = [new_solution[i:i+segment_size] for i in range(0, n, segment_size)]

    segment_scores = []
    for seg in segments:
        seg_cost = 0
        for i in range(len(seg)-1):
            if worst_obj == 0:
                seg_cost += distance_matrix_1[seg[i], seg[i+1]]
            elif worst_obj == 1:
                seg_cost += distance_matrix_2[seg[i], seg[i+1]]
            else:
                seg_cost += distance_matrix_3[seg[i], seg[i+1]]
        segment_scores.append(seg_cost)

    if np.random.rand() < 0.7:
        top_segments = np.argsort(segment_scores)[-min(2, len(segments)):]
        for i in top_segments:
            if np.random.rand() < 0.5:
                segments[i] = segments[i][::-1]
            else:
                swap_idx = np.random.choice([j for j in range(len(segments)) if j != i])
                segments[i], segments[swap_idx] = segments[swap_idx], segments[i]
    else:
        for seg_idx in range(len(segments)):
            if np.random.rand() < 0.4:
                seg = segments[seg_idx]
                if len(seg) > 2:
                    node_costs = []
                    for k in range(len(seg)):
                        if k == 0:
                            prev_node = segments[seg_idx-1][-1] if seg_idx > 0 else segments[-1][-1]
                        else:
                            prev_node = seg[k-1]
                        if k == len(seg)-1:
                            next_node = segments[seg_idx+1][0] if seg_idx < len(segments)-1 else segments[0][0]
                        else:
                            next_node = seg[k+1]

                        if worst_obj == 0:
                            cost = distance_matrix_1[prev_node, seg[k]] + distance_matrix_1[seg[k], next_node]
                        elif worst_obj == 1:
                            cost = distance_matrix_2[prev_node, seg[k]] + distance_matrix_2[seg[k], next_node]
                        else:
                            cost = distance_matrix_3[prev_node, seg[k]] + distance_matrix_3[seg[k], next_node]
                        node_costs.append(cost)

                    worst_node = np.argmax(node_costs)
                    if worst_node == 0:
                        continue
                    new_seg = np.delete(seg, worst_node)
                    insert_pos = np.random.randint(0, len(new_seg)+1)
                    new_seg = np.insert(new_seg, insert_pos, seg[worst_node])
                    segments[seg_idx] = new_seg

    new_solution = np.concatenate(segments)

    unique_nodes, counts = np.unique(new_solution, return_counts=True)
    if len(unique_nodes) < n:
        missing_nodes = np.setdiff1d(np.arange(n), unique_nodes)
        for node in missing_nodes:
            best_pos = 0
            best_cost = float('inf')
            for pos in range(n):
                cost = 0
                if worst_obj == 0:
                    cost += distance_matrix_1[new_solution[pos-1], node] + distance_matrix_1[node, new_solution[pos]]
                elif worst_obj == 1:
                    cost += distance_matrix_2[new_solution[pos-1], node] + distance_matrix_2[node, new_solution[pos]]
                else:
                    cost += distance_matrix_3[new_solution[pos-1], node] + distance_matrix_3[node, new_solution[pos]]
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            new_solution = np.insert(new_solution, best_pos, node)

    return new_solution[:n]

