    segment_scores = []
    for i in range(n):
        for j in range(i+1, min(i+5, n)):
            obj1 = distance_matrix_1[new_solution[i-1], new_solution[j]] - distance_matrix_1[new_solution[i-1], new_solution[i]] - distance_matrix_1[new_solution[j-1], new_solution[j]]
