            else:
                new_solution[best_i:best_j] = np.roll(new_solution[best_i:best_j], -1)

    # Probabilistic node swapping
    for _ in range(2):
        if np.random.rand() < 0.5:
            a, b = np.random.choice(n, 2, replace=False)
            if np.random.rand() < obj_weights[0]:
                if distance_matrix_1[new_solution[a-1], new_solution[b]] + distance_matrix_1[new_solution[b-1], new_solution[a]] < distance_matrix_1[new_solution[a-1], new_solution[a]] + distance_matrix_1[new_solution[b-1], new_solution[b]]:
